export const ARCHITECTURE_CHECKPOINT_VERSION = 1;

const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const workspaceRoot = path.resolve(packageRoot, '..');
const reportsDir = path.join(packageRoot, 'reports');

function relative(filePath) {
  return path.relative(workspaceRoot, filePath).replace(/\\/g, '/');
}

function readJsonReport(name) {
  const filePath = path.join(reportsDir, name);
  try {
    return {
      ok: true,
      file: relative(filePath),
      report: JSON.parse(fs.readFileSync(filePath, 'utf8')),
    };
  } catch (error) {
    return {
      ok: false,
      file: relative(filePath),
      error: error.message,
      report: null,
    };
  }
}

function channelSummary(audit = {}) {
  return (audit.channels || []).map((channel) => ({
    channelId: channel.channelId,
    status: channel.status,
    stableImportCount: channel.publicApiUsage?.stableImportCount || 0,
    compatibilityImportCount: channel.publicApiUsage?.compatibilityImportCount || 0,
    internalImportCount: channel.publicApiUsage?.internalImportCount || 0,
    recommendedAction: channel.publicApiUsage?.recommendedAction || null,
    liveEntrypointCount: (channel.liveEntrypoints || []).length,
    liveEntrypoints: (channel.liveEntrypoints || []).map((entrypoint) => ({
      actionId: entrypoint.actionId,
      status: entrypoint.status,
      lifecycleProfileId: entrypoint.lifecycleProfileId,
      lifecycleValidationStatus: entrypoint.lifecycleValidationStatus,
    })),
  }));
}

function reportBinding({ key, filename, required = true }) {
  const loaded = readJsonReport(filename);
  const report = loaded.report || {};
  const ok = loaded.ok && (!required || report.ok === true);
  const hash = reportHashForFileId(report, filename);
  return {
    key,
    filename,
    file: loaded.file,
    ok,
    status: report.status || (loaded.ok ? 'unknown_report_status' : 'missing_report'),
    hash,
    blockers: Array.isArray(report.blockers) ? report.blockers : [],
    error: loaded.error || null,
    report,
  };
}

